```cpp
// add+modify_eas_records.hpp
#pragma once

#include <filesystem>
#include <map>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>
#include <vector>

#include "eas_common.hpp"
using namespace sqlgen;
using namespace sqlgen::literals;

template<typename T>
void add_eas_records(const std::string& table_name,
                     const std::vector<T>& records) {

  // Connect to the database
  auto conn_result = sqlgen::sqlite::connect(db_path);
  if (!conn_result) {
    // Handle connection error
    return;
  }

  auto conn = conn_result.value();

  // Insert records based on table type
  if constexpr (std::is_same_v<T, Student>) {
    for (const auto& record : records) {
      auto result = sqlgen::write(conn, record);
      if (!result) {
        // Handle insertion error
        return;
      }
    }
  } else if constexpr (std::is_same_v<T, Course>) {
    for (const auto& record : records) {
      auto result = sqlgen::write(conn, record);
      if (!result) {
        // Handle insertion error
        return;
      }
    }
  } else if constexpr (std::is_same_v<T, Score>) {
    for (const auto& record : records) {
      auto result = sqlgen::write(conn, record);
      if (!result) {
        // Handle insertion error
        return;
      }
    }
  } else if constexpr (std::is_same_v<T, Major>) {
    for (const auto& record : records) {
      auto result = sqlgen::write(conn, record);
      if (!result) {
        // Handle insertion error
        return;
      }
    }
  }
}

void modify_eas_records_by_id(const std::string& table_name,
                              const std::string& record_id,
                              const std::string& col_name,
                              const auto& new_value) {
  // Connect to the database
  auto conn_result = sqlgen::sqlite::connect(db_path);
  if (!conn_result) {
    // Handle connection error
    return;
  }

  auto conn = conn_result.value();

  // Modify record based on table name and primary key
  if (table_name == "Student") {
    auto result = conn.and_then([&](auto&& conn) {
      return sqlgen::update<Student>(conn)
          .set(col_name == new_value)
          .where("SNo"_c == record_id);
    });
  } else if (table_name == "Course") {
    uint32_t id = std::stoi(record_id);
    auto result = conn.and_then([&](auto&& conn) {
      return sqlgen::update<Course>(conn)
          .set(col_name == new_value)
          .where("CID"_c == id);
    });
  } else if (table_name == "Score") {
    uint32_t id = std::stoi(record_id);
    auto result = conn.and_then([&](auto&& conn) {
      return sqlgen::update<Score>(conn)
          .set(col_name == new_value)
          .where("ScID"_c == id);
    });
  } else if (table_name == "Major") {
    uint32_t id = std::stoi(record_id);
    auto result = conn.and_then([&](auto&& conn) {
      return sqlgen::update<Major>(conn)
          .set(col_name == new_value)
          .where("MID"_c == id);
    });
  }
}

void delete_eas_records_by_id(const std::string& table_name,
                               const std::string& record_id) {
  // Connect to the database
  auto conn_result = sqlgen::sqlite::connect(db_path);
  if (!conn_result) {
    // Handle connection error
    return;
  }

  auto conn = conn_result.value();

  // Delete record based on table name and primary key
  if (table_name == "Student") {
    auto result = conn.and_then([&](auto&& conn) {
      return sqlgen::delete_from<Student>(conn).where("SNo"_c == record_id);
    });
  } else if (table_name == "Course") {
    uint32_t id = std::stoi(record_id);
    auto result = conn.and_then([&](auto&& conn) {
      return sqlgen::delete_from<Course>(conn).where("CID"_c == id);
    });
  } else if (table_name == "Score") {
    uint32_t id = std::stoi(record_id);
    auto result = conn.and_then([&](auto&& conn) {
      return sqlgen::delete_from<Score>(conn).where("ScID"_c == id);
    });
  } else if (table_name == "Major") {
    uint32_t id = std::stoi(record_id);
    auto result = conn.and_then([&](auto&& conn) {
      return sqlgen::delete_from<Major>(conn).where("MID"_c == id);
    });
  }
}
```

Key implementation details:

1. **`add_eas_records`**: Uses template specialization to handle different table types. For each record in the vector, it calls `sqlgen::write()` to insert into the database.

2. **`modify_eas_records_by_id`**: Uses `sqlgen::update()` with `.set()` and `.where()` clauses to modify specific columns based on the primary key. Handles different primary key types (string for Student.SNo, uint32_t for others).

3. **`delete_eas_records_by_id`**: Uses `sqlgen::delete_from()` with `.where()` clause to delete records based on primary key. Converts string record_id to appropriate types when needed.

The implementation follows the `sqlgen` library patterns seen in the code fragments, using the connection pattern, where clauses, and the specific SQL generation functions provided by the library.

