#pragma once

#include <ranges>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace batch_insert_products {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string name;
  float price;
  std::string category;
  int stock;
};

/**
 * Function: Perform efficient batch insertion of product data using a transaction.
 * 
 * @param products List of products to insert
 * @return true if all inserts succeed, false otherwise
 */
bool batch_insert_products(const std::vector<Product>& products) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite database and perform operations in a transaction
  auto result = sqlite::connect("test_db.sqlite")
      .and_then(drop_table<Product> | if_exists)
      .and_then(create_table<Product>)
      .and_then([&products](auto&& conn) {
          return conn.transaction([&products](auto&& trans_conn) {
              return trans_conn.and_then(insert(products));
          });
      });

  // Return true if all operations succeeded, false otherwise
  return result.has_value();
}

}  // namespace batch_insert_products
```

Key points about this implementation:

1. **Database Connection**: Uses `sqlite::connect("test_db.sqlite")` to connect to the SQLite database.

2. **Table Management**: 
   - `drop_table<Product> | if_exists` drops the table if it exists
   - `create_table<Product>` creates the Product table with the defined structure

3. **Transaction Handling**: Uses `conn.transaction()` to wrap the insert operation in a transaction, ensuring atomicity.

4. **Batch Insertion**: `insert(products)` performs the batch insertion of all products.

5. **Error Handling**: Returns `true` if all operations succeed (result has value), `false` otherwise.

The `sqlgen` library automatically handles:
- Mapping the `Product` struct to the database table schema
- Generating the appropriate SQL statements
- Transaction management
- Error propagation through the monadic `and_then` pattern

The function follows the exact requirements: connects to the database, drops and creates the table, begins a transaction, inserts all products, and commits if successful.

