```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>
#include <vector>

namespace query_high_value_orders {

struct Customer {
  sqlgen::PrimaryKey<int> customer_id;
  std::string name;
};

struct Order {
  sqlgen::PrimaryKey<int> order_id;
  int customer_id;
  double total_amount;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
};

struct OrderView {
  static constexpr const char* tablename = "HighValueOrderView";
  static constexpr bool is_view = true;
  sqlgen::PrimaryKey<int> order_id;
  std::string name;
  double total_amount;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
};

std::vector<OrderView> query_high_value_orders() {
  // Connect to the SQLite database
  auto db = sqlgen::sqlite::connect("test_db.sqlite");

  // Build the query using sqlgen's select syntax
  auto query = sqlgen::select(
    sqlgen::column<Order>("order_id"),
    sqlgen::column<Customer>("name"), 
    sqlgen::column<Order>("total_amount"),
    sqlgen::column<Order>("order_date")
  ).from<Order>()
   .inner_join<Customer>().on(sqlgen::column<Order>("customer_id") == sqlgen::column<Customer>("customer_id"))
   .where(sqlgen::column<Order>("total_amount") > 1000.0)
   .order_by(sqlgen::column<Order>("total_amount"), sqlgen::DESC);

  // Execute query and map results to OrderView objects
  std::vector<OrderView> results;
  auto rows = db.execute(query);

  for (const auto& row : rows) {
    OrderView orderView;
    orderView.order_id = std::get<0>(row);
    orderView.name = std::get<1>(row);
    orderView.total_amount = std::get<2>(row);
    orderView.order_date = std::get<3>(row);
    results.push_back(orderView);
  }

  return results;
