    auto conn = sqlgen::sqlite::connect("test_db.sqlite");
    if (!conn) {
      return false;
    }

    // Create the Product table first
    auto create_table_result = sqlgen::exec(
        *conn, 
        sqlgen::transpilation::to_create_table<Product, sqlgen::if_not_exists>()
    );

    if (!create_table_result) {
      return false;
    }

    // Create standard index on category
    auto idx_category_result = sqlgen::exec(
        *conn,
        sqlgen::create_index<sqlgen::if_not_exists>("idx_product_category")
            .on<Product>(&Product::category)
    );

    if (!idx_category_result) {
      return false;
    }

    // Create unique index on sku
    auto idx_sku_result = sqlgen::exec(
        *conn,
        sqlgen::create_index<sqlgen::if_not_exists, sqlgen::Unique>("idx_product_sku")
            .on<Product>(&Product::sku)
    );

    if (!idx_sku_result) {
      return false;
    }

    // Create composite index on (name, price)
    auto idx_name_price_result = sqlgen::exec(
        *conn,
        sqlgen::create_index<sqlgen::if_not_exists>("idx_product_name_price")
            .on<Product>(&Product::name, &Product::price)
    );

    if (!idx_name_price_result) {
      return false;
    }

    return true;
  }

}  // namespace schema_manage_indexes
