```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace soft_delete_records {

struct Document {
  sqlgen::PrimaryKey<int> doc_id;
  std::string title;
  int is_deleted = 0;
  std::optional<sqlgen::DateTime> deleted_at;
};

bool soft_delete_records(const std::vector<int>& ids) {
    // Connect to SQLite database
    const auto conn = sqlgen::sqlite::connect("test_db.sqlite");
    if (!conn) {
        return false;
    }

    // Create a transaction for batch updates
    auto transaction = conn->begin_transaction();
    if (!transaction) {
        return false;
    }

    try {
        // Update each document in the list
        for (const auto& id : ids) {
            // Create a Document object with the updated values
            Document updated_doc;
            updated_doc.doc_id = id;
            updated_doc.is_deleted = 1;
            updated_doc.deleted_at = sqlgen::DateTime::now();

            // Create the WHERE condition
            auto where_condition = sqlgen::where(sqlgen::field(&Document::doc_id) == id);

            // Perform the update
            auto result = sqlgen::update<Document>(conn, updated_doc, where_condition);
            if (!result) {
                transaction->rollback();
                return false;
            }
        }

        // Commit the transaction
        if (!transaction->commit()) {
            return false;
        }

        return true;
    } catch (const std::exception& e) {
        transaction->rollback();
        return false;
    }
}

}  // namespace soft_delete_records
```

This implementation:

1. Connects to the SQLite database "test_db.sqlite"
2. Uses a transaction to ensure all updates succeed or fail together
3. Iterates through the list of document IDs
4. For each ID, creates a Document object with the updated values (`is_deleted = 1` and `deleted_at` set to current timestamp)
5. Uses `sqlgen::update` with a WHERE condition to update only the specific document
6. Commits the transaction if all updates succeed, or rolls back if any fail
7. Returns true on success, false on failure

The code follows the sqlgen library patterns seen in the provided examples, using the library's update functionality with proper error handling and transaction management.

