```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace analyze_social_network {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
  std::string email;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> join_date;
  std::optional<std::string> city;
};

struct Friendship {
  int user1_id;
  int user2_id;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> friendship_date;
};

struct FriendConnection {
  std::string user1_name;
  std::string user2_name;
  int mutual_friends_count;
};

struct UserFriendCount {
  std::string username;
  int friend_count;
};

struct FriendOfFriend {
  std::string user_name;
  std::string friend_of_friend_name;
  std::string mutual_friend_name;
};

struct SameCityNonFriend {
  std::string user1_name;
  std::string user2_name;
  std::string city;
};

/**
 * Analyze social network data by creating temporary SQL tables for User and Friendship.
 * Returns: std::vector<FriendConnection>.
 */
std::vector<FriendConnection> analyze_social_network_impl(const std::vector<User>& users, const std::vector<Friendship>& friendships) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Create an in-memory SQLite database
  auto db = sqlgen::sqlite::connect(":memory:");

  // Create tables
  db.and_then(create_table<User>)
    .and_then(create_table<Friendship>)
    .and_then(begin_transaction)
    .and_then(insert(std::ref(users)))
    .and_then(insert(std::ref(friendships)))
    .and_then(commit);

  // 1. Find mutual friends using SELF-JOIN
  auto mutual_friends_query = select(
    col<&User::username>("u1_username"),
    col<&User::username>("u2_username"),
    count(col<&Friendship::user1_id>("f1_user_id2"))("mutual_friends_count")
  ).from<User>("u1")
   .inner_join<Friendship>("f1").on(col<&User::user_id>("u1") == col<&Friendship::user1_id>("f1"))
   .inner_join<Friendship>("f2").on(col<&Friendship::user2_id>("f1") == col<&Friendship::user1_id>("f2"))
   .inner_join<User>("u2").on(col<&Friendship::user2_id>("f2") == col<&User::user_id>("u2"))
   .where(col<&User::user_id>("u1") < col<&User::user_id>("u2"))
   .and_where(exists(
     select(1).from<Friendship>("f3")
     .where(col<&Friendship::user1_id>("f3") == col<&User::user_id>("u1"))
     .and_where(col<&Friendship::user2_id>("f3") == col<&User::user_id>("u2"))
   ))
   .group_by(col<&User::user_id>("u1"), col<&User::user_id>("u2"))
   .having(count(col<&Friendship::user1_id>("f1_user_id2")) > 0);

  // 2. Find users with more than average number of friends using nested query
  auto avg_friends_subquery = select(count("*")("friend_count"))
    .from<Friendship>()
    .group_by(col<&Friendship::user1_id>());

  auto popular_users_query = select(
    col<&User::user_id>(),
    col<&User::username>(),
    count(col<&Friendship::user2_id>())("friend_count")
  ).from<User>()
   .left_join<Friendship>().on(col<&User::user_id>() == col<&Friendship::user1_id>())
   .group_by(col<&User::user_id>(), col<&User::username>())
   .having(count(col<&Friendship::user2_id>()) > avg_friends_subquery)
   .order_by(count(col<&Friendship::user2_id>()).desc());

  // 3. Find friend-of-friend relationships
  auto friend_of_friend_query = select(
    col<&User::username>("u1_username"),
    col<&User::username>("u3_username"),
    col<&User::username>("u2_username")("mutual_friend")
  ).from<User>("u1")
   .inner_join<Friendship>("f1").on(col<&User::user_id>("u1") == col<&Friendship::user1_id>("f1"))
   .inner_join<User>("u2").on(col<&Friendship::user2_id>("f1") == col<&User::user_id>("u2"))
   .inner_join<Friendship>("f2").on(col<&User::user_id>("u2") == col<&Friendship::user1_id>("f2"))
   .inner_join<User>("u3").on(col<&Friendship::user2_id>("f2") == col<&User::user_id>("u3"))
   .where(col<&User::user_id>("u1") != col<&User::user_id>("u3"))
   .and_where(not_exists(
     select(1).from<Friendship>("f3")
     .where(col<&Friendship::user1_id>("f3") == col<&User::user_id>("u1"))
     .and_where(col<&Friendship::user2_id>("f3") == col<&User::user_id>("u3"))
   ));

  // 4. Count friends per user
  auto friends_per_user_query = select(
    col<&User::username>(),
    count(col<&Friendship::user2_id>())("friend_count")
  ).from<User>()
   .left_join<Friendship>().on(col<&User::user_id>() == col<&Friendship::user1_id>())
   .group_by(col<&User::user_id>(), col<&User::username>())
   .order_by(count(col<&Friendship::user2_id>()).desc());

  // 5. Find users in the same city who are not yet friends
  auto same_city_recommendation_query = select(
    col<&User::username>("u1_username"),
    col<&User::username>("u2_username"),
    col<&User::city>("city")
  ).from<User>("u1")
   .inner_join<User>("u2").on(col<&User::city>("u1") == col<&User::city>("u2"))
   .where(col<&User::user_id>("u1") < col<&User::user_id>("u2"))
   .and_where(col<&User::city>("u1").is_not_null())
   .and_where(not_exists(
     select(1).from<Friendship>("f")
     .where((col<&Friendship::user1_id>("f") == col<&User::user_id>("u1")
            .and_(col<&Friendship::user2_id>("f") == col<&User::user_id>("u2")))
     .or_(col<&Friendship::user1_id>("f") == col<&User::user_id>("u2")
         .and_(col<&Friendship::user2_id>("f") == col<&User::user_id>("u1")))
   )));

  // Execute the mutual friends query and return results
  auto result = db.and_then(execute(mutual_friends_query));

  std::vector<FriendConnection> connections;
  if (result) {
    for (const auto& row : *result) {
      connections.push_back(FriendConnection{
        .user1_name = std::get<0>(row),
        .user2_name = std::get<1>(row),
        .mutual_friends_count = std::get<2>(row)
      });
    }
  }

  return connections;
}

}  // namespace analyze_social_network
```

