```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace calculate_order_metrics {

struct OrderItem {
  sqlgen::PrimaryKey<int> item_id;
  int order_id;
  int product_id;
  double unit_price;
  int quantity;
  std::optional<double> discount_rate;
  std::optional<double> tax_rate;
};

struct OrderMetrics {
  int item_id;
  int order_id;
  int product_id;
  double unit_price;
  int quantity;
  double discount_rate;
  double tax_rate;
  double gross_total;
  double discounted_total;
  double final_total;
  double unit_cost;
  int quantity_group;
  double estimated_profit;
};

/**
 * Calculate per-item order metrics by loading the provided items into a temporary SQLite table
 * and evaluating SQL expressions for totals, discounts, taxes, cost, grouping, and estimated profit.
 * @param items Vector of OrderItem records to analyze.
 * @return std::vector<OrderMetrics> Analysis results for each order item.
 */
std::vector<OrderMetrics> calculate_order_metrics_impl(const std::vector<OrderItem>& items) {
  // Connect to an in-memory SQLite database
  auto conn_result = sqlgen::sqlite::connect(":memory:");
  if (!conn_result) {
    throw std::runtime_error("Failed to connect to database: " + conn_result.error().what());
  }
  auto conn = *conn_result;

  // Create a temporary table for OrderItem data
  const char* create_table_sql = R"(
    CREATE TEMPORARY TABLE OrderItem (
      item_id INTEGER PRIMARY KEY,
      order_id INTEGER NOT NULL,
      product_id INTEGER NOT NULL,
      unit_price REAL NOT NULL,
      quantity INTEGER NOT NULL,
      discount_rate REAL,
      tax_rate REAL
    )
  )";

  auto execute_result = conn->execute(create_table_sql);
  if (!execute_result) {
    throw std::runtime_error("Failed to create table: " + execute_result.error().what());
  }

  // Insert the order items into the temporary table
  if (!items.empty()) {
    auto insert_stmt = sqlgen::insert_into<OrderItem>().columns(
      &OrderItem::item_id,
      &OrderItem::order_id,
      &OrderItem::product_id,
      &OrderItem::unit_price,
      &OrderItem::quantity,
      &OrderItem::discount_rate,
      &OrderItem::tax_rate
    );

    auto insert_result = conn->insert(insert_stmt, items.begin(), items.end());
    if (!insert_result) {
      throw std::runtime_error("Failed to insert data: " + insert_result.error().what());
    }
  }

  // Execute the query to calculate metrics
  const char* metrics_sql = R"(
    SELECT 
      item_id,
      order_id,
      product_id,
      unit_price,
      quantity,
      COALESCE(discount_rate, 0) as discount_rate,
      COALESCE(tax_rate, 0) as tax_rate,
      (unit_price * quantity) as gross_total,
