```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace replace_text_in_notes {

struct Note {
  sqlgen::PrimaryKey<int> note_id;
  std::string content;
};

struct UpdatedNote {
  sqlgen::PrimaryKey<int> note_id;
  std::string updated_content;
};

/**
 * description: replace_text_in_notes.
 * This function demonstrates how to replace text in notes using sqlgen update API.
 * It replaces all occurrences of "foo" with "bar" in the content column of the Note table.
 * Returns: std::vector<UpdatedNote>.
 */
std::vector<UpdatedNote> replace_text_in_notes() {
  // Connect to SQLite database
  const auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // First, read all existing notes
  auto notes = sqlgen::read<std::vector<Note>>(conn).value();

  // Update each note by replacing "foo" with "bar"
  for (const auto& note : notes) {
    Note updated_note = note;

    // Replace all occurrences of "foo" with "bar"
    size_t pos = 0;
    while ((pos = updated_note.content.find("foo", pos)) != std::string::npos) {
      updated_note.content.replace(pos, 3, "bar");
      pos += 3; // Move past the replaced text
    }

    // Update the note in the database
    sqlgen::write(conn, updated_note);
  }

  // Read the updated notes for verification
  auto updated_notes = sqlgen::read<std::vector<Note>>(conn).value();

  // Convert to UpdatedNote structure for return
  std::vector<UpdatedNote> result;
  for (const auto& note : updated_notes) {
    UpdatedNote updated_note;
    updated_note.note_id = note.note_id;
    updated_note.updated_content = note.content;
    result.push_back(updated_note);
  }

  return result;
}

}  // namespace replace_text_in_notes
```

