```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace cascade_delete_demo {

struct Parent {
  sqlgen::PrimaryKey<int> parent_id;
  std::string name;
};

struct Child {
  sqlgen::PrimaryKey<int> child_id;
  sqlgen::ForeignKey<int, Parent, "parent_id"> parent_id;
  std::string note;
};

/**
 * Demonstrates cascade delete behavior in SQLite using foreign key constraints.
 * Returns: bool.
 */
bool cascade_delete_demo() {
  // Connect to SQLite database
  sqlgen::sqlite::Connection conn("test_db.sqlite");

  // Create tables
  conn.execute("DROP TABLE IF EXISTS Child");
  conn.execute("DROP TABLE IF EXISTS Parent");

  conn.execute(R"(
    CREATE TABLE Parent (
      parent_id INTEGER PRIMARY KEY,
      name TEXT NOT NULL
    )
  )");

  conn.execute(R"(
    CREATE TABLE Child (
      child_id INTEGER PRIMARY KEY,
      parent_id INTEGER,
      note TEXT,
      FOREIGN KEY (parent_id) REFERENCES Parent(parent_id) ON DELETE CASCADE
    )
  )");

  // Enable foreign key constraints (important for SQLite)
  conn.execute("PRAGMA foreign_keys = ON");

  // Insert parent records
  Parent p1{.parent_id = 1, .name = "Parent1"};
  Parent p2{.parent_id = 2, .name = "Parent2"};

  conn.insert(p1);
  conn.insert(p2);

  // Insert child records with same parent_id
  Child c1{.child_id = 1, .parent_id = 1, .note = "Child of Parent1"};
  Child c2{.child_id = 2, .parent_id = 1, .note = "Another child of Parent1"};
  Child c3{.child_id = 3, .parent_id = 2, .note = "Child of Parent2"};

  conn.insert(c1);
  conn.insert(c2);
  conn.insert(c3);

  // Verify initial child count for parent_id = 1
  auto initial_children = conn.select<Child>(sqlgen::where(&Child::parent_id) == 1);
  if (initial_children.size() != 2) {
    return false; // Initial setup failed
  }

  // Delete parent with parent_id = 1
  conn.execute("DELETE FROM Parent WHERE parent_id = 1");

  // Verify that child rows with parent_id = 1 are automatically deleted
  auto remaining_children = conn.select<Child>(sqlgen::where(&Child::parent_id) == 1);

  // Verify that child with parent_id = 2 still exists
  auto child_of_parent2 = conn.select<Child>(sqlgen::where(&Child::parent_id) == 2);

  // Clean up
  conn.execute("DROP TABLE IF EXISTS Child");
  conn.execute("DROP TABLE IF EXISTS Parent");

  // Return verification result
  return remaining_children.empty() && child_of_parent2.size() == 1;
}

}  // namespace cascade_delete_demo
```

