TEST(sqlite, select_from_read_to_vector) {
  using namespace sqlgen;
  auto conn = sqlite::connect("test_db.sqlite").value();
  drop<Book>(conn);
  create_table<Book>(conn);
  insert(conn, std::vector<Book>{{1, "A", 100}, {2, "B", 200}, {3, "C", 150}});
  auto rows = select_from_read_to_vector();
  ASSERT_EQ(rows.size(), 3);
  EXPECT_GE(rows[0].pages, rows[1].pages);
}

