#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace analyze_department_employees {

struct Department {
  sqlgen::PrimaryKey<int> department_id;
  std::string department_name;
  std::string location;
};

struct Employee {
  sqlgen::PrimaryKey<int> employee_id;
  int department_id;
  std::string first_name;
  std::string last_name;
  double salary;
};

struct JoinResult {
  std::optional<std::string> department_name;
  std::optional<std::string> first_name;
  std::optional<std::string> last_name;
  std::optional<double> salary;
};

struct JoinAnalysis {
  std::vector<JoinResult> inner_join_results;
  std::vector<JoinResult> left_join_results;
  std::vector<JoinResult> right_join_results;
  std::vector<JoinResult> full_join_results;
};

/**
 * analyze_department_employees
 * Provides data-join analysis between Department and Employee input collections by
 * creating temporary SQL tables, inserting the provided rows, and executing a
 * variety of join queries to produce join-output samples.
 * Returns: JoinAnalysis.
 */
JoinAnalysis analyze_department_employees_impl(const std::vector<Department>& depts, const std::vector<Employee>& emps) {
  JoinAnalysis analysis;

  // Create SQLite connection to in-memory database
  auto conn = sqlgen::sqlite::connect(":memory:").value();

  // Create tables
  conn.and_then(sqlgen::drop<Department> | sqlgen::if_exists)
      .and_then(sqlgen::drop<Employee> | sqlgen::if_exists)
      .and_then(sqlgen::create<Department>)
      .and_then(sqlgen::create<Employee>);

  // Insert data
  sqlgen::write(conn, depts);
  sqlgen::write(conn, emps);

  // Perform INNER JOIN
  auto inner_join_query = sqlgen::read<JoinResult> | 
                         sqlgen::from<Department, Employee> |
                         sqlgen::on(sqlgen::field<&Department::department_id> == sqlgen::field<&Employee::department_id>);

  auto inner_result = conn.and_then(inner_join_query);
  if (inner_result) {
    analysis.inner_join_results = inner_result.value();
  }

  // Perform LEFT JOIN (Employee LEFT JOIN Department)
  auto left_join_query = sqlgen::read<JoinResult> |
                        sqlgen::from<Employee> |
                        sqlgen::left_join<Department> |
                        sqlgen::on(sqlgen::field<&Employee::department_id> == sqlgen::field<&Department::department_id>);

  auto left_result = conn.and_then(left_join_query);
  if (left_result) {
    analysis.left_join_results = left_result.value();
  }

  // Perform RIGHT JOIN (Employee RIGHT JOIN Department)
  // Note: SQLite doesn't natively support RIGHT JOIN, so we simulate it with LEFT JOIN
  auto right_join_query = sqlgen::read<JoinResult> |
                         sqlgen::from<Department> |
                         sqlgen::left_join<Employee> |
                         sqlgen::on(sqlgen::field<&Department::department_id> == sqlgen::field<&Employee::department_id>);

  auto right_result = conn.and_then(right_join_query);
  if (right_result) {
    analysis.right_join_results = right_result.value();
  }

  // Perform FULL JOIN (simulated using UNION of LEFT and RIGHT joins since SQLite doesn't support FULL JOIN)
  auto full_join_left_part = sqlgen::read<JoinResult> |
                            sqlgen::from<Employee> |
                            sqlgen::left_join<Department> |
                            sqlgen::on(sqlgen::field<&Employee::department_id> == sqlgen::field<&Department::department_id>);

  auto full_join_right_part = sqlgen::read<JoinResult> |
                             sqlgen::from<Department> |
                             sqlgen::left_join<Employee> |
                             sqlgen::on(sqlgen::field<&Department::department_id> == sqlgen::field<&Employee::department_id>) |
                             sqlgen::where(sqlgen::field<&Employee::employee_id> == sqlgen::null);

  // Since sqlgen doesn't directly support UNION in the way we need for this complex case,
  // we'll manually combine the results
  std::vector<JoinResult> full_join_results;

  // Add left join results
  auto left_for_full = conn.and_then(full_join_left_part);
  if (left_for_full) {
    full_join_results.insert(full_join_results.end(), 
                            left_for_full.value().begin(), 
                            left_for_full.value().end());
  }

  // Add right join results that are not in left join (departments without employees)
  auto right_for_full = conn.and_then(full_join_right_part);
  if (right_for_full) {
    full_join_results.insert(full_join_results.end(), 
                            right_for_full.value().begin(), 
                            right_for_full.value().end());
  }

  analysis.full_join_results = full_join_results;

  return analysis;
}

}  // namespace analyze_department_employees

