#include <optional>

namespace coalesce_function {

struct Profile {
  sqlgen::PrimaryKey<int> id;
  std::optional<std::string> nickname;
};

struct NicknameResult {
  std::string display_name;
};

/**
 * This function demonstrates COALESCE usage.
 * Returns: query value.
 */
inline auto coalesce_function() {
    using namespace sqlgen;

    // Create a table object for the Profile struct
    auto profiles = Table<Profile>("profiles");

    // Construct the query using COALESCE
    auto query = select(
        coalesce(profiles.nickname, "Anonymous").as("display_name")
    ).from(profiles);

    return query;
}

}  // namespace coalesce_function
```

The key elements of this implementation:

1. **Table Creation**: `auto profiles = Table<Profile>("profiles");` creates a table object for the Profile struct.

2. **COALESCE Function**: `coalesce(profiles.nickname, "Anonymous")` uses sqlgen's `coalesce` function to handle the nullable nickname field, providing "Anonymous" as the fallback value.

3. **Alias**: `.as("display_name")` gives the result column a meaningful name that matches the `NicknameResult` struct field.

4. **Query Construction**: The `select().from()` pattern builds the complete SQL query.

The function returns a query object that, when executed, will select from the profiles table and use COALESCE to return either the nickname or "Anonymous" if the nickname is NULL.

