namespace update_inventory_stock {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  int stock;
};

bool update_inventory_stock(const std::unordered_map<int, int>& received) {
  using namespace sqlgen;
  using namespace sqlgen::literals;
  auto conn_res = sqlite::connect("test_db.sqlite");
  if (!conn_res) return false;
  create_table<Product>(conn_res.value());

  // Begin transaction using the connection
  auto txn_res = conn_res.value().begin_transaction();
  if (!txn_res) return false;

  for (const auto& [pid, qty] : received) {
    // Use parameterized query instead of string concatenation
    std::string sql = "UPDATE Product SET stock = stock + ? WHERE product_id = ?";
    auto stmt_res = dynamic::Statement::parse(sql);
    if (!stmt_res) return false;

    // Execute with parameters
    auto exec_res = conn_res.value().execute(stmt_res.value(), {qty, pid});
    if (!exec_res) {
      // Rollback on error
      conn_res.value().rollback();
      return false;
    }
  }

  // Commit the transaction
  auto commit_res = conn_res.value().commit();
  return commit_res.has_value();
}

}  // namespace update_inventory_stock

